parameters.blocksUi:
={
  "blocks": [
    {
      "type": "header",
      "text": {
        "type": "plain_text",
        "text": ":rotating_light: n8n Workflow Error",
        "emoji": true
      }
    },
    {
      "type": "section",
      "fields": [
        {
          "type": "mrkdwn",
          "text": "*Workflow:*\n{{ $json.workflow?.name ?? 'Unknown Workflow' }}"
        },
        {
          "type": "mrkdwn",
          "text": "*Workflow ID:*\n{{ $json.workflow?.id ?? 'Unknown' }}"
        },
        {
          "type": "mrkdwn",
          "text": "*Execution ID:*\n{{ $json.execution?.id ?? 'Unknown' }}"
        },
        {
          "type": "mrkdwn",
          "text": "*Mode:*\n{{ $json.execution?.mode ?? 'Unknown' }}"
        }
      ]
    },
    { "type": "divider" },
    {
      "type": "section",
      "fields": [
        {
          "type": "mrkdwn",
          "text": "*Last Node Executed:*\n{{ $json.execution?.lastNodeExecuted ?? 'Unknown' }}"
        },
        {
          "type": "mrkdwn",
          "text": "*Retry Of:*\n{{ $json.execution?.retryOf ?? 'None' }}"
        }
      ]
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*Error Message:*\n```{{ $json.execution?.error?.message ?? 'No error message provided' }}```\n*Stacktrace (if present):*\n```{{ $json.execution?.error?.stack ?? 'No stacktrace provided' }}```"
      }
    },
    { "type": "divider" },
    {
      "type": "actions",
      "elements": [
        {
          "type": "button",
          "action_id": "open_workflow",
          "text": { "type": "plain_text", "text": "Open Workflow", "emoji": true },
          "url": "{{ $json.execution?.url ? $json.execution.url.split('/execution/')[0] + '/workflow/' + ($json.workflow?.id ?? '') : '#' }}"
        }
      ]
    },
    {
      "type": "context",
      "elements": [
        {
          "type": "mrkdwn",
          "text": "This message was generated automatically from an n8n execution error."
        }
      ]
    }
  ]
}
